class Base {
  static count = 0;
  id: number;
  constructor() { this.id = ++Base.count; }
  who(): string { return "b"; }
}
class Der extends Base {
  who(): string { return "d" + super.who(); }
}
function main(): void {
  const D: any = Der;
  console.log(new D().id, D.count);
  const list: Base[] = [new Base(), new Der()];
  const view: any = list;
  console.log(view.map((x: Base) => x.who()).join());
}
